for cutoff in (2.0, 3.0):
    window = [z for z in zeros if abs(z.imag) <= cutoff]
    print(cutoff, window, harmonic(window))

from typing import Sequence

def harmonic(points: Sequence[complex]) -> complex:
    if any(z == 0 for z in points):
        raise ValueError("zero has no reciprocal")
    return sum((1 / z for z in points), 0j)

window = [1 + 2j, 1 - 2j, 3 + 0j]
value = harmonic(window)
print("harmonic =", value)
print("expected real value =", 11 / 15)
assert abs(value.imag) < 1e-12

