from typing import Iterable

def reciprocal_harmonic(points: Iterable[complex]) -> complex:
    total = 0j
    for point in points:
        if point == 0:
            raise ValueError("all points must be nonzero")
        total += 1 / point
    return total

from dataclasses import dataclass
from typing import Sequence

@dataclass(frozen=True)
class BoundReport:
    count: int
    harmonic: complex
    delta: float | None
    upper_bound: float

def separated_window_report(points: Sequence[complex]) -> BoundReport:
    if any(z == 0 for z in points):
        raise ValueError("all points must be nonzero")
    h = sum((1 / z for z in points), 0j)
    if not points:
        return BoundReport(0, h, None, 0.0)
    delta = min(abs(z) for z in points)
    return BoundReport(len(points), h, delta, len(points) / delta)

from fractions import Fraction

def vieta_reciprocal_harmonic(l: Fraction, q: Fraction) -> Fraction:
    if q == 0:
        raise ValueError("q must be nonzero")
    return l / q

